/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, ArrayComprehension, Dummy, Float, Mul, Sym, add, doit, isUnsolved, mul, rational, symbols, sympify, xreplace } from '../../src';
import { at, pyLen, sympyMatches, sympyStr } from '../sympy-str';

describe("doctests of sympy.tensor.array.array_comprehension", () => {
  it("a.doit()", () => {
    const [j, i] = symbols('j i');
    expect(sympyStr(doit(ArrayComprehension(add(j, mul(10, i)), [i, rational(1), rational(4)], [j, rational(1), rational(3)])))).toBe('[[11, 12, 13], [21, 22, 23], [31, 32, 33], [41, 42, 43]]');
  });
  it("b.doit()", () => {
    const [j, i, k] = symbols('j i k');
    expect(sympyStr(doit(ArrayComprehension(add(j, mul(10, i)), [i, rational(1), rational(4)], [j, rational(1), k])))).toBe('ArrayComprehension(10*i + j, (i, 1, 4), (j, 1, k))');
  });
  it("a.free_symbols", () => {
    expect(sympyStr(new Set())).toBe('set()');
  });
  it("b.free_symbols", () => {
    const k = new Sym('k');
    expect(sympyStr(new Set([k]))).toBe('{k}');
  });
  it("a.function", () => {
    const [j, i] = symbols('j i');
    expect(sympyStr(add(j, mul(10, i)))).toBe('10*i + j');
  });
  it("a.is_shape_numeric", () => {
    const [j, i] = symbols('j i');
    expect(sympyStr(ArrayComprehension(add(j, mul(10, i)), [i, rational(1), rational(4)], [j, rational(1), rational(3)]).isShapeNumeric)).toBe('True');
  });
  it("b.is_shape_numeric", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("a.limits", () => {
    const [i, j] = symbols('i j');
    expect(sympyMatches([[i, rational(1), rational(4)], [j, rational(1), rational(3)]], '((i, 1, 4), (j, 1, 3))')).toBe(true);
  });
  it("a.rank()", () => {
    const [j, i] = symbols('j i');
    expect(sympyStr(ArrayComprehension(add(j, mul(10, i)), [i, rational(1), rational(4)], [j, rational(1), rational(3)]).rank())).toBe('2');
  });
  it("a.shape", () => {
    const [j, i] = symbols('j i');
    expect(sympyMatches([at(ArrayComprehension(add(j, mul(10, i)), [i, rational(1), rational(4)], [j, rational(1), rational(3)]).shape, 0), at(ArrayComprehension(add(j, mul(10, i)), [i, rational(1), rational(4)], [j, rational(1), rational(3)]).shape, 1)], '(4, 3)')).toBe(true);
  });
  it("b.shape", () => {
    const [j, i, k] = symbols('j i k');
    expect(sympyMatches([at(ArrayComprehension(add(j, mul(10, i)), [i, rational(1), rational(4)], [j, rational(1), add(3, k)]).shape, 0), at(ArrayComprehension(add(j, mul(10, i)), [i, rational(1), rational(4)], [j, rational(1), add(3, k)]).shape, 1)], '(4, k + 3)')).toBe(true);
  });
  // a result object that did not come from the library
  //   a.tolist()
  //   => [[11, 12, 13], [21, 22, 23], [31, 32, 33], [41, 42, 43]]
  it.todo("a.tolist()");
  it("a.tomatrix()", () => {
    const [j, i] = symbols('j i');
    expect(sympyStr(ArrayComprehension(add(j, mul(10, i)), [i, rational(1), rational(4)], [j, rational(1), rational(3)]).tomatrix())).toBe('Matrix([[11, 12, 13], [21, 22, 23], [31, 32, 33], [41, 42, 43]])');
  });
  it("a.variables", () => {
    const [i, j] = symbols('i j');
    expect(sympyStr([i, j])).toBe('[i, j]');
  });
  // a callback parameter outside its callback
  //   a.doit()
  //   => [1, 1, 1, 1]
  it.todo("a.doit() (2)");
  // a callback parameter outside its callback
  //   b.doit()
  //   => [2, 3, 4, 5]
  it.todo("b.doit() (2)");
  it("a", () => {
    const [j, i] = symbols('j i');
    expect(sympyStr(ArrayComprehension(add(j, mul(10, i)), [i, 1, 4], [j, 1, 3]))).toBe('ArrayComprehension(10*i + j, (i, 1, 4), (j, 1, 3))');
  });
});

